// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "../../contracts/Land_record.sol";

interface Vm {
    function assume(bool condition) external pure;
    function prank(address msgSender) external;
    function expectRevert() external;
}

contract LandRecordSymbolicTest {
    Vm internal constant vm = Vm(address(uint160(uint256(keccak256("hevm cheat code")))));

    LandRecord public landRecord;

    function setUp() public {
        landRecord = LandRecord(payable(VmContractHelper40(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D).deployCode({_artifact: "contracts/Land_record.sol:LandRecord", _args: encodeArgs36(DeployHelper36.FoundryPpConstructorArgs(3 days))})));
    }

    /// @dev Formally proves that ANY caller without PAUSER_ROLE cannot pause the contract
    function check_unauthorized_pause_reverts(address caller) public {
        vm.assume(caller != address(this));
        vm.assume(!landRecord.hasRole(landRecord.PAUSER_ROLE(), caller));

        vm.prank(caller);
        vm.expectRevert();
        landRecord.pause();
    }

    /// @dev Formally proves the initial paused state is always false
    function check_initial_paused_state() public view {
        require(!landRecord.paused(), "Initial paused state must be false");
    }
}
import {DeployHelper36, encodeArgs36} from "foundry-pp/DeployHelper36.sol";

interface VmContractHelper40 {
    function deployCode(string memory _artifact) external returns (address);
    function deployCode(string memory _artifact, bytes32 _salt) external returns (address);
    function deployCode(string memory _artifact, bytes memory _args) external returns (address);
    function deployCode(string memory _artifact, bytes memory _args, bytes32 _salt) external returns (address);
    function deployCode(string memory _artifact, uint256 _value) external returns (address);
    function deployCode(string memory _artifact, uint256 _value, bytes32 _salt) external returns (address);
    function deployCode(string memory _artifact, bytes memory _args, uint256 _value) external returns (address);
    function deployCode(string memory _artifact, bytes memory _args, uint256 _value, bytes32 _salt) external returns (address);
    function getCode(string memory _artifact) external view returns (bytes memory);
}

